//! The shape of a protocol interface, as the generated tables state it.
//!
//! A message's argument kinds are what the wire codec needs to read an
//! event or write a request: the wire carries no types, so the receiver
//! has to know, per object, which interface it is and therefore which
//! signature an opcode names. `INTERFACES` is that knowledge, generated by
//! `build.rs` from the pinned XMLs and never written by hand.

/// One argument's wire type.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArgKind {
    /// A signed 32-bit integer.
    Int,
    /// An unsigned 32-bit integer.
    Uint,
    /// A 24.8 signed fixed-point number.
    Fixed,
    /// A NUL-terminated string, padded to four; `nullable` allows length 0.
    Str { nullable: bool },
    /// An object id; `nullable` allows 0.
    Object { nullable: bool },
    /// A new object id. With `interface: None` the wire carries the
    /// interface name and version first -- `wl_registry.bind`'s shape.
    NewId { interface: Option<&'static str> },
    /// A length-prefixed byte array, padded to four.
    Array,
    /// A file descriptor, carried out of band as an `SCM_RIGHTS` message.
    Fd,
}

/// A request or an event.
#[derive(Debug)]
pub struct Msg {
    pub name: &'static str,
    /// The interface version that introduced it.
    pub since: u32,
    /// A request that destroys its object.
    pub destructor: bool,
    pub args: &'static [ArgKind],
}

/// An interface: its requests indexed by opcode, its events likewise.
#[derive(Debug)]
pub struct Interface {
    pub name: &'static str,
    pub version: u32,
    pub requests: &'static [Msg],
    pub events: &'static [Msg],
}

impl Interface {
    /// The interface named `name`, if the pinned protocols declare it: for
    /// a name read off the wire. An interface baud names in its own source
    /// is `protocol::<name>::INTERFACE`, which walks nothing.
    pub fn named(name: &str) -> Option<&'static Interface> {
        crate::protocol::INTERFACES
            .iter()
            .copied()
            .find(|i| i.name == name)
    }
}
